// UnaryOption is a configuration option for unary (request-response) calls.
// It provides a namespace to distinguish unary-specific options.
type UnaryOption struct {
	F func(o *client.Options, di *utils.Slice)
}

// StreamOption is a configuration option for streaming calls.
// It provides a namespace to distinguish streaming-specific options.
type StreamOption struct {
	F func(o *client.Options, di *utils.Slice)
}

// TTHeaderStreamingOption is a configuration option for TTHeader streaming calls.
// It provides a namespace for protocol-specific streaming options.
type TTHeaderStreamingOption struct {
	F func(o *client.Options, di *utils.Slice)
}

