func (u UnaryOption) AsOption() Option {
	return Option{F: u.F}
}

// AsOption converts StreamOption to the generic Option type.
func (s StreamOption) AsOption() Option {
	return Option{F: s.F}
}

// AsOption converts TTHeaderStreamingOption to the generic Option type.
func (t TTHeaderStreamingOption) AsOption() Option {
	return Option{F: t.F}
}
